referenceSolutions.javascript:
function fixedPanelsProofStrip(readings, k) {
  const a=readings; let out=[];
  let s=0;for(let i=0;i<a.length;i++){s+=a[i];if(i>=k)s-=a[i-k];if(i>=k-1)out.push(s);}
  return out;
}

